// Package broker provides transport-agnostic, generic messaging functions.
//
// A Channel[T] describes where messages of type T travel. Publish, Subscribe,
// Request and Respond work on any channel and any payload type; the
// transport is a small Broker interface (see natsbroker for NATS). Code
// generated by asyncapi-gen only declares models, channels and thin types
// that call these functions. Payloads can be checked against their JSON
// Schemas with WithValidator (see schemavalidate).
//
// Each generated type asks only for the part of Broker it uses (Publisher,
// Requester, Subscriber or PubSub), so an application can pass its own
// implementation, or wrap one of the provided brokers, to add tracing,
// authentication and the like.
package broker

import "context"

// Publisher is the transport of a generated Producer.
type Publisher interface {
	// Publish sends m to m.Subject.
	Publish(ctx context.Context, m *Message) error
}

// Requester is the transport of a generated Client.
type Requester interface {
	// Request sends m and waits for a single reply. ctx carries the deadline.
	Request(ctx context.Context, m *Message) (*Message, error)
}

// Subscriber is the transport of a generated Consumer.
type Subscriber interface {
	// Subscribe calls h for every message matching cfg.Subject. It fails
	// when cfg.Source is set to something the transport does not support.
	//
	// The context passed to h becomes the context of the application's
	// handler, and of any reply sent for the message. A wrapping transport
	// extracts trace headers or deadlines into it before calling the h it
	// was given.
	//
	// h returns nil when the message was handled. Brokers with
	// acknowledgements (see jsbroker) ack on nil, redeliver on an error, and
	// drop messages whose error wraps ErrMalformed. Others ignore it.
	Subscribe(cfg SubConfig, h func(context.Context, *Message) error) (Subscription, error)
}

// PubSub is the transport of a generated Server, which subscribes to
// requests and publishes the replies.
type PubSub interface {
	Publisher
	Subscriber
}

// Broker is a transport supporting every operation.
type Broker interface {
	Publisher
	Requester
	Subscriber
}

// SubConfig describes a subscription. SubOptions fill it in.
type SubConfig struct {
	// Subject may contain "*" wildcards for single tokens.
	Subject string
	// Queue load balances messages across subscribers sharing the name.
	Queue string
	// Source is a transport-specific origin of the messages, such as a
	// JetStream consumer (see jsbroker.From). Nil means the transport's
	// default, e.g. a core NATS subscription.
	Source any
}

// Endpoint is where a receive operation listens: the subject pattern and
// queue name it subscribes with. Generated code declares one per receive
// operation, e.g. to fill in a JetStream consumer's FilterSubject.
type Endpoint struct {
	Subject string
	Queue   string
}

// Subscription is an active subscription.
type Subscription interface {
	Unsubscribe() error
}

// Message is a message as carried by a Broker.
type Message struct {
	Subject string
	// Reply is the subject a response should be published to, if any.
	Reply  string
	Header Header
	Data   []byte
}

// Header holds message headers.
type Header map[string][]string

// Get returns the first value of key, or "".
func (h Header) Get(key string) string {
	if v := h[key]; len(v) > 0 {
		return v[0]
	}
	return ""
}

// Set replaces the values of key.
func (h Header) Set(key, value string) { h[key] = []string{value} }
